def tau(n):
    """Calculates the number of positive divisors of n."""
    if n == 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

results = {}
for k in range(1, 16):
    n = 2 * (k**3)
    lhs = tau(n)
    rhs = 2 * k
    is_equal = lhs == rhs
    results[k] = {
        '2k^3': n,
        'tau(2k^3)': lhs,
        '2k': rhs,
        'Equal': is_equal
    }

# Format results for easy reading and writing to notes
output = "k | 2k^3 | tau(2k^3) | 2k | Match?\n"
output += "-------------------------------------------\n"
for k, data in results.items():
    match_str = "Yes" if data['Equal'] else "No"
    output += f"{k:2} | {data['2k^3']:4} | {data['tau(2k^3)']:<9} | {data['2k']:2} | {match_str}\n"

print(output)

def count_divisors(n):
    """Calculates the number of positive divisors (tau function) of n."""
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            count += 1
            # n//i is also a divisor, unless i*i = n
            if i * i != n:
                count += 1
        i += 1
    return count

# Alternative method using prime factorization for robustness (though the above is fine for small numbers)
def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau(n):
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    tau = 1
    for exponent in factors.values():
        tau *= (exponent + 1)
    return tau

results = []
for k in range(16, 41):
    N = 2 * (k**3)
    tau_N = calculate_tau(N)
    two_k = 2 * k
    match = "Yes" if tau_N == two_k else "No"
    results.append((k, N, tau_N, two_k, match))

# Formatting output for notes
output = "k | 2k^3 | $\\tau(2k^3)$ | 2k | Match?\n"
output += "---------------------------------------------------\n"
for k, N, tau_N, two_k, match in results:
    output += f"{k:2} | {N:4} | {tau_N:12} | {two_k:2} | {match}\n"

print(output)

