import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def check_condition(k):
    if k <= 0:
        return False
    LHS = count_divisors(2 * k**3)
    RHS = 2 * k
    return LHS == RHS

# Test candidates from B
