import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    # Iterate up to sqrt(n)
    limit = int(math.isqrt(n))
    for i in range(1, limit + 1):
        if n % i == 0:
            # If i is a divisor, then n/i is also a divisor
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

print("Testing k from 41 to 100...")
solutions = []
for k in range(41, 101):
    N = 2 * (k**3)
    tau_N = count_divisors(N)
    target = 2 * k

    if tau_N == target:
        solutions.append(k)
        print(f"Solution found: k = {k}. tau({N}) = {tau_N}, 2k = {target}")

if not solutions:
    print("\nNo new solutions found in the range 41 <= k <= 100.")
else:
    print(f"\nNew solutions found: {solutions}")
